You are given a Python program that solves the employee partitioning problem. Your task is to translate this program into C++17 while preserving the exact stdin/stdout behavior.

The problem is as follows: A company wants to divide its employees into two teams such that the absolute difference between the total skill levels of the two teams is minimized. You are to compute this minimum absolute difference.

Input:
- The first line contains an integer `n` (1 ≤ n ≤ 100) — the number of employees.
- The second line contains `n` integers — the skill levels of the employees (positive integers, sum ≤ 10⁴).

Output:
- A single integer: the minimum possible absolute difference between the sums of the two teams.

Examples:
```
Input:
5
1 6 11 5 11

Output:
0
```

```
Input:
4
3 1 4 2

Output:
0
```

The provided Python program uses dynamic programming to find the smallest difference. Translate it exactly into C++17, ensuring:
- Input is read from `stdin`.
- Output is written to `stdout`.
- The logic and algorithm are preserved (including the DP table construction and backtracking for the best half-sum).
- No extra output or formatting.

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int min_diff_partition(int n, const vector<int>& skills) {
    int total_skill = 0;
    for (int skill : skills) {
        total_skill += skill;
    }

    vector<vector<bool>> dp(n + 1, vector<bool>(total_skill / 2 + 1, false));
    dp[0][0] = true;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= total_skill / 2; ++j) {
            if (j >= skills[i - 1]) {
                dp[i][j] = dp[i - 1][j] || dp[i - 1][j - skills[i - 1]];
            } else {
                dp[i][j] = dp[i - 1][j];
            }
        }
    }

    int half_sum = total_skill / 2;
    int min_diff = total_skill;
    for (int j = half_sum; j >= 0; --j) {
        if (dp[n][j]) {
            min_diff = total_skill - 2 * j;
            break;
        }
    }

    return min_diff;
}

int main() {
    int n;
    cin >> n;
    vector<int> skills(n);
    for (int i = 0; i < n; ++i) {
        cin >> skills[i];
    }

    int result = min_diff_partition(n, skills);
    cout << result << endl;

    return 0;
}
```

