def is_reachable(N, S):
    position = 0
    for char in S:
        if char == 'L':
            position -= 1
        elif char == 'R':
            position += 1

    if position == N:
        return "Yes"

    for i in range(len(S)):
        if S[i] == '*':
            temp_position = 0
            for j, char in enumerate(S):
                if i == j:
                    continue
                if char == 'L':
                    temp_position -= 1
                elif char == 'R':
                    temp_position += 1
            if temp_position == N:
