import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();
        long s = scanner.nextLong();

        List<Long> dragons = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            dragons.add(scanner.nextLong());
        }

        // Sort dragons in ascending order (we want to fight weaker dragons first)
        Collections.sort(dragons);

        boolean canWin = true;
        for (long dragon : dragons) {
