#include <iostream>
#include <vector>
#include <algorithm>
#include <sstream>
#include <climits>
#include <cctype>
#include <cmath>

std::vector<int> minimize_difference_and_sort(std::vector<int> arr, int x) {
    // Sort the array to find the lexicographically smallest order
    std::sort(arr.begin(), arr.end());

    // Find the value in `arr` that minimizes the absolute difference with `x`
    int min_diff = INT_MAX;
    int best_element = arr[0];

    for (int element : arr) {
        int diff = std::abs(element - x);
        if (diff < min_diff) {
            min_diff = diff;
            best_element = element;
        }
    }

    // Remove the best_element from its current position
    auto it = std::find(arr.begin(), arr.end(), best_element);
    arr.erase(it);

    // Insert best_element at the beginning
    arr.insert(arr.begin(), best_element);

    return arr;
}

