#include <vector>
#include <string>
#include <algorithm>
#include <sstream>

std::string largestNumber(std::vector<int>& nums) {
    // Convert integers to strings
    std::vector<std::string> nums_str;
    for (int num : nums) {
        nums_str.push_back(std::to_string(num));
    }

    // Custom sort: for two strings a and b, compare a+b vs b+a
    std::sort(nums_str.begin(), nums_str.end(), [](const std::string& a, const std::string& b) {
        return a + b > b + a;
